from __future__ import annotations

import json
import os
import unittest
from pathlib import Path


class RetrievalEvaluationSmokeTests(unittest.TestCase):
    """Validate retrieval-evaluation artifacts generated by CI.

    The full retrieval evaluation depends on FAISS and a SentenceTransformer
    model download, so CI runs the actual command explicitly and points this
    test at the resulting JSON report through RETRIEVAL_EVAL_REPORT.
    Local unit-test runs skip this contract unless that environment variable is
    provided.
    """

    def test_retrieval_evaluation_report_contract(self):
        report_path = os.environ.get("RETRIEVAL_EVAL_REPORT")
        if not report_path:
            self.skipTest("RETRIEVAL_EVAL_REPORT is not set; CI validates this artifact.")

        path = Path(report_path)
        self.assertTrue(path.exists(), msg=f"Missing retrieval evaluation report: {path}")

        with path.open("r", encoding="utf-8") as f:
            report = json.load(f)

        self.assertIn("config", report)
        self.assertIn("summary", report)
        self.assertIn("queries", report)
        self.assertIsInstance(report["queries"], list)
        self.assertGreater(len(report["queries"]), 0)

        summary = report["summary"]
        expected_summary_keys = {
            "num_queries",
            "mean_hit_at_k",
            "mean_precision_at_k",
            "mean_recall_at_k",
            "mean_reciprocal_rank",
        }
        self.assertTrue(expected_summary_keys.issubset(summary))
        self.assertEqual(int(summary["num_queries"]), len(report["queries"]))

        for key in expected_summary_keys - {"num_queries"}:
            value = float(summary[key])
            self.assertGreaterEqual(value, 0.0, msg=key)
            self.assertLessEqual(value, 1.0, msg=key)

        required_query_keys = {
            "query_id",
            "question",
            "relevant_doc_ids",
            "retrieved_doc_ids",
            "hit_at_k",
            "precision_at_k",
            "recall_at_k",
            "reciprocal_rank",
        }
        for query_result in report["queries"]:
            self.assertTrue(required_query_keys.issubset(query_result))
            self.assertTrue(query_result["question"].strip())
            self.assertIsInstance(query_result["relevant_doc_ids"], list)
            self.assertIsInstance(query_result["retrieved_doc_ids"], list)


if __name__ == "__main__":
    unittest.main()
